import QtQuick
import QtQuick3D

Rectangle {
    anchors.fill: parent
    color: "#1a1a2e"

    View3D {
        anchors.fill: parent
        environment: SceneEnvironment {
            clearColor: "#1a1a2e"
            backgroundMode: SceneEnvironment.Color
            antialiasingMode: SceneEnvironment.MSAA
        }

        PerspectiveCamera { z: 400 }
        DirectionalLight {
            eulerRotation.x: -30
            eulerRotation.y: -30
        }

        SpinningCube {
            scale: Qt.vector3d(1.5, 1.5, 1.5)
        }
    }

    Text {
        anchors.bottom: parent.bottom
        anchors.horizontalCenter: parent.horizontalCenter
        anchors.bottomMargin: 20
        text: "Edit SpinningCube.qml to change the cube's behavior"
        color: "#808080"
        font.pixelSize: 14
    }
}

import QtQuick
import QtQuick3D

Model {
    property color cubeColor: "#0e639c"

    source: "#Cube"
    materials: PrincipledMaterial {
        baseColor: cubeColor
        metalness: 0.5
        roughness: 0.3
    }

    NumberAnimation on eulerRotation.y {
        from: 0; to: 360
        duration: 4000
        loops: Animation.Infinite
    }
    NumberAnimation on eulerRotation.x {
        from: 0; to: 360
        duration: 6000
        loops: Animation.Infinite
    }
}
